export default {
  async main(env, ctx) {
    const { params } = ctx;

    const url = "https://news.ycombinator.com/news";
    const timeoutMs = 15000;

    const meta = {
      url,
      timeoutMs,
      fetchedAt: new Date().toISOString(),
      errors: [],
      warnings: [],
    };

    try {
      const controller = new AbortController();
      const t = setTimeout(() => controller.abort(), timeoutMs);
      const res = await fetch(url, {
        signal: controller.signal,
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; Maia-HN-Fetcher/1.0)",
          Accept: "text/html,application/xhtml+xml",
        },
      });
      clearTimeout(t);

      if (!res.ok) {
        meta.errors.push(`HTTP error: ${res.status} ${res.statusText}`);
        return {
          outputs: {
            ok: false,
            url,
            html: "",
            status: res.status,
            meta,
          },
        };
      }

      const html = await res.text();
      return {
        outputs: {
          ok: true,
          url,
          status: res.status,
          html,
          meta,
        },
      };
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      meta.errors.push(`Fetch failed: ${msg}`);
      if (e && typeof e === "object" && "name" in e && String(e.name) === "AbortError") {
        meta.warnings.push("Request timeout: suggest retrying later");
      }
      return {
        outputs: {
          ok: false,
          url,
          html: "",
          status: null,
          meta,
        },
      };
    }
  },
};

import * as cheerio from "cheerio";

export default {
  async main(env, ctx) {
    const { upstream } = ctx;

    const fetchResult = upstream.fetch_hn_html?.data;
    const html = String(fetchResult?.outputs?.html ?? "");
    const baseUrl = String(fetchResult?.outputs?.url ?? "https://news.ycombinator.com/news");

    const meta = {
      errors: [],
      warnings: [],
      parsedAt: new Date().toISOString(),
      baseUrl,
    };

    if (!html) {
      meta.errors.push("No parseable HTML (upstream fetch is empty)");
      return {
        outputs: {
          items: [],
          count: 0,
          meta,
        },
      };
    }

    try {
      const $ = cheerio.load(html);

      const items = [];
      const rows = $("tr.athing").slice(0, 10);

      rows.each((idx, el) => {
        const row = $(el);
        const a = row.find("span.titleline > a").first();
        const title = a.text().trim();
        const href = (a.attr("href") || "").trim();

        let url = "";
        try {
          if (href) url = new URL(href, "https://news.ycombinator.com/").toString();
        } catch {
          url = href;
        }

        // HN pages usually have rank, but use idx+1 as fallback for safety
        const rankText = row.find("span.rank").first().text().trim();
        const rank = Number((rankText || "").replace(".", "")) || idx + 1;

        items.push({
          rank,
          title,
          url,
        });
      });

      const cleaned = items
        .filter((x) => x && typeof x.title === "string" && x.title.trim())
        .slice(0, 10)
        .map((x, i) => ({
          rank: Number(x.rank) || i + 1,
          title: String(x.title || "").trim(),
          url: String(x.url || "").trim(),
        }));

      if (cleaned.length === 0) {
        meta.warnings.push("Parsed 0 results: HN DOM structure may have changed");
      }

      return {
        outputs: {
          items: cleaned,
          count: cleaned.length,
          meta,
        },
      };
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      meta.errors.push(`Parsing failed: ${msg}`);
      return {
        outputs: {
          items: [],
          count: 0,
          meta,
        },
      };
    }
  },
};

