export default {
  async main(env, ctx) {
    const { upstream } = ctx;

    const parsed = upstream.parse_top10?.data;
    const items = Array.isArray(parsed?.outputs?.items) ? parsed.outputs.items : [];

    const meta = {
      errors: [],
      warnings: [],
      builtAt: new Date().toISOString(),
      wroteFile: false,
      filePath: null,
      fileName: "hacker-news-top10.md",
    };

    const lines = [];

    lines.push("# Hacker News Top 10");
    lines.push("");
    lines.push(`- Generated at: ${new Date().toISOString()}`);
    lines.push(`- Source: https://news.ycombinator.com/news`);
    lines.push("");

    for (let i = 0; i < Math.min(items.length, 10); i++) {
      const it = items[i] || {};
      const title = String(it.title || "").trim() || "(No title)";
      const url = String(it.url || "").trim();

      // Output each item as Markdown list:
      // 1. [Title](URL)
      //    URL: ...
      if (url) {
        const safeTitle = title.replace(/\[/g, "\\[").replace(/\]/g, "\\]");
        lines.push(`${i + 1}. [${safeTitle}](${url})`);
        lines.push(`   - URL: ${url}`);
      } else {
        lines.push(`${i + 1}. ${title}`);
        lines.push(`   - URL: `);
      }

      if (i < Math.min(items.length, 10) - 1) lines.push("");
    }

    const text = lines.join("\n");

    // Write to actual artifact (explicit artifact registration)
    try {
      const r = await ctx.artifacts.writeText(meta.fileName, text, { kind: "file", summary: "HN Top 10 Markdown" });
      meta.wroteFile = true;
      meta.filePath = r?.absPath || null;
    } catch (e) {
      meta.errors.push(`Failed to write/register artifact: ${e instanceof Error ? e.message : String(e)}`);
    }

    return {
      outputs: {
        text,
        count: Math.min(items.length, 10),
        file_name: meta.fileName,
        file_path: meta.filePath,
        wrote_file: meta.wroteFile,
        meta,
      },
    };
  },
};
